const inventoryAccountBalances = `-- name: InventoryAccountBalances :many
SELECT a.id, a.code, a.name, COALESCE(sum(l.debit - l.credit), 0)::numeric AS balance
  FROM gl_accounts a
  LEFT JOIN gl_journal_lines l ON l.property_id = a.property_id AND l.account_id = a.id
 WHERE a.tenant_id = $1 AND a.property_id = $2 AND a.account_type = 'ASSET' AND a.statement_group = 'INVENTORIES'
 GROUP BY a.id, a.code, a.name
 HAVING COALESCE(sum(l.debit - l.credit), 0) <> 0
 ORDER BY a.code
`

type InventoryAccountBalancesParams struct {
	TenantID   int64
	PropertyID int64
}

type InventoryAccountBalancesRow struct {
	ID      int64
	Code    string
	Name    string
	Balance decimal.Decimal
}

// F9: a property that already has a balance on its inventory accounts (hand-entered bills and journals) cannot open the module until the accountant has cleared them.
// The balance of an account is read from the journals, as the general ledger does it.
func (q *Queries) InventoryAccountBalances(ctx context.Context, arg InventoryAccountBalancesParams) ([]InventoryAccountBalancesRow, error) {
	rows, err := q.db.Query(ctx, inventoryAccountBalances, arg.TenantID, arg.PropertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []InventoryAccountBalancesRow{}
	for rows.Next() {
		var i InventoryAccountBalancesRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Name,
			&i.Balance,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

