const listItems = `-- name: ListItems :many

SELECT i.id, i.tenant_id, i.property_id, i.code, i.name, i.category_id, i.stock_unit_id, i.reference_cost, i.default_supplier_id, i.barcode, i.note, i.is_active, i.version, i.created_at, i.created_by, i.updated_at, i.updated_by, c.code AS category_code, c.name AS category_name, c.kind AS category_kind, u.code AS stock_unit_code,
       COALESCE((SELECT sum(b.qty) FROM inv_balances b WHERE b.property_id = i.property_id AND b.item_id = i.id AND ($1::bigint IS NULL OR b.warehouse_id = $1)), 0)::numeric AS qty_on_hand,
       COALESCE((SELECT sum(b.value) FROM inv_balances b WHERE b.property_id = i.property_id AND b.item_id = i.id AND ($1::bigint IS NULL OR b.warehouse_id = $1)), 0)::numeric AS value_on_hand,
       EXISTS (SELECT 1 FROM inv_levels l LEFT JOIN inv_balances b ON b.warehouse_id = l.warehouse_id AND b.item_id = l.item_id
                WHERE l.property_id = i.property_id AND l.item_id = i.id AND l.min_qty > 0 AND COALESCE(b.qty, 0) < l.min_qty)::boolean AS below_min,
       EXISTS (SELECT 1 FROM inv_balances b WHERE b.property_id = i.property_id AND b.item_id = i.id AND b.qty < 0)::boolean AS below_zero
  FROM inv_items i
  JOIN inv_categories c ON c.property_id = i.property_id AND c.id = i.category_id
  JOIN inv_units u ON u.property_id = i.property_id AND u.id = i.stock_unit_id
 WHERE i.tenant_id = $2 AND i.property_id = $3
   AND ($4::bigint IS NULL OR i.category_id = $4)
   AND ($5::boolean IS NULL OR i.is_active = $5)
   AND ($6::text IS NULL OR i.code ILIKE '%' || $6 || '%' OR i.name ILIKE '%' || $6 || '%' OR i.barcode = $6)
   AND (NOT $7::boolean OR EXISTS (SELECT 1 FROM inv_levels l LEFT JOIN inv_balances b ON b.warehouse_id = l.warehouse_id AND b.item_id = l.item_id
                WHERE l.property_id = i.property_id AND l.item_id = i.id AND l.min_qty > 0 AND COALESCE(b.qty, 0) < l.min_qty))
 ORDER BY i.name, i.id
 LIMIT $9 OFFSET $8
`

